import bisect


def schedule(intervals):
    items = []
    for i, iv in enumerate(intervals):
        s, e, w = iv
        if e <= s:
            raise ValueError("interval %d has end <= start" % i)
        if w < 0:
            raise ValueError("interval %d has a negative weight" % i)
        items.append((e, s, w, i))
    if not items:
        return (0, [])
    items.sort()
    n = len(items)
    ends = [it[0] for it in items]
    best = [0] * (n + 1)
    take = [False] * (n + 1)
    par = [0] * (n + 1)
    for j in range(1, n + 1):
        e, s, w, idx = items[j - 1]
        p = bisect.bisect_left(ends, s)
        cand = w + best[p]
        if cand >= best[j - 1]:
            best[j] = cand
            take[j] = True
            par[j] = p
        else:
            best[j] = best[j - 1]
    chosen = []
    j = n
    while j > 0:
        if take[j]:
            chosen.append(items[j - 1][3])
            j = par[j]
        else:
            j -= 1
    chosen.sort()
    return (best[n], chosen)

