    got = schedule([])
    if not isinstance(got, tuple) or len(got) != 2:
        raise AssertionError('schedule([]) must return a 2-tuple, got %r' % (got,))
    if got[0] != 0 or not isinstance(got[1], list) or got[1] != []:
        raise AssertionError('schedule([]) must be (0, []), got %r' % (got,))


