    got = schedule([(2.5, 7, 3)])
    if not isinstance(got, tuple) or len(got) != 2:
        raise AssertionError('expected a 2-tuple, got %r' % (got,))
    if got[0] != 3 or not isinstance(got[1], list) or got[1] != [0]:
        raise AssertionError('expected (3, [0]), got %r' % (got,))


