def t_performance_large():
    import time
    m = 30000
    ivs = []
    expected = []
    for k in range(m):
        b = 4 * k
        ivs.append((b, b + 2, 4))
        ivs.append((b + 2, b + 4, 4))
        expected.append(len(ivs))
        ivs.append((b, b + 4, 10))
        if k % 5 == 4:
            ivs.append((4 * (k - 4), 4 * (k + 1), 40))
    t0 = time.perf_counter()
    got = schedule(ivs)
    dt = time.perf_counter() - t0
    if got[0] != 10 * m:
        raise AssertionError('expected total weight %d, got %r' % (10 * m, got[0]))
    picked = list(got[1])
    if picked != expected:
        raise AssertionError('wrong selection on the large instance: got %d indices (want %d), head %r want %r'
                             % (len(picked), len(expected), picked[:6], expected[:6]))
    if dt > 20.0:
        raise AssertionError('too slow: %.1f s for n=%d, an O(n log n) solution is required' % (dt, len(ivs)))


