import bisect
import math
from collections import deque


def _valid_cap(capacity):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be an int >= 1")


class SlidingWindow:
    __slots__ = ("_cap", "_buf", "_srt")

    def __init__(self, capacity):
        _valid_cap(capacity)
        self._cap = capacity
        self._buf = deque()
        self._srt = []

    @property
    def capacity(self):
        return self._cap

    def __len__(self):
        return len(self._buf)

    def push(self, x):
        if not isinstance(x, (int, float)):
            raise ValueError("value must be an int or float")
        try:
            v = float(x)
        except (OverflowError, ValueError):
            raise ValueError("value must be a finite int or float")
        if not math.isfinite(v):
            raise ValueError("value must be finite")
        evicted = None
        if len(self._buf) >= self._cap:
            evicted = self._buf.popleft()
            i = bisect.bisect_left(self._srt, evicted)
            self._srt.pop(i)
        self._buf.append(v)
        bisect.insort(self._srt, v)
        return evicted

    def snapshot(self):
        return list(self._buf)

    def mean(self):
        n = len(self._buf)
        if n == 0:
            return None
        return math.fsum(self._buf) / n

    def variance(self):
        n = len(self._buf)
        if n < 2:
            return None
        m = math.fsum(self._buf) / n
        return math.fsum((v - m) * (v - m) for v in self._buf) / (n - 1)

    def median(self):
        n = len(self._srt)
        if n == 0:
            return None
        if n % 2:
            return self._srt[n // 2]
        return (self._srt[n // 2 - 1] + self._srt[n // 2]) / 2.0

    def min(self):
        if not self._srt:
            return None
        return self._srt[0]

    def max(self):
        if not self._srt:
            return None
        return self._srt[-1]

    def resize(self, new_capacity):
        _valid_cap(new_capacity)
        evicted = []
        while len(self._buf) > new_capacity:
            v = self._buf.popleft()
            i = bisect.bisect_left(self._srt, v)
            self._srt.pop(i)
            evicted.append(v)
        self._cap = new_capacity
        return evicted

    def clear(self):
        self._buf.clear()
        del self._srt[:]

