import math


class SlidingWindow:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or capacity < 1:
            raise ValueError("capacity must be a positive int")
        self._cap = capacity
        self._buf = []
        self._sum = 0.0
        self._sumsq = 0.0
        self._min = None
        self._max = None

    @property
    def capacity(self):
        return self._cap

    def __len__(self):
        return len(self._buf)

    def push(self, x):
        if not isinstance(x, (int, float)):
            raise ValueError("value must be numeric")
        v = float(x)
        evicted = None
        if len(self._buf) >= self._cap:
            evicted = self._buf.pop(0)
            self._sum -= evicted
            self._sumsq -= evicted * evicted
        self._buf.append(v)
        self._sum += v
        self._sumsq += v * v
        if self._min is None or v < self._min:
            self._min = v
        if self._max is None or v > self._max:
            self._max = v
        return evicted

    def snapshot(self):
        return self._buf

    def mean(self):
        n = len(self._buf)
        if n == 0:
            return None
        return self._sum / n

    def variance(self):
        n = len(self._buf)
        if n < 2:
            return None
        return (self._sumsq - self._sum * self._sum / n) / (n - 1)

    def median(self):
        n = len(self._buf)
        if n == 0:
            return None
        s = sorted(self._buf)
        if n % 2:
            return s[n // 2]
        return (s[n // 2 - 1] + s[n // 2]) / 2.0

    def min(self):
        if not self._buf:
            return None
        return self._min

    def max(self):
        if not self._buf:
            return None
        return self._max

    def resize(self, new_capacity):
        if not isinstance(new_capacity, int) or new_capacity < 1:
            raise ValueError("capacity must be a positive int")
        evicted = []
        while len(self._buf) > new_capacity:
            v = self._buf.pop()
            self._sum -= v
            self._sumsq -= v * v
            evicted.append(v)
        self._cap = new_capacity
        return evicted

    def clear(self):
        self._buf = []
        self._sum = 0.0
        self._sumsq = 0.0

