import math as _math
import random as _random
import time as _time
from fractions import Fraction as _Fraction


def _rel_close(got, want, tol, label):
    if got is None:
        raise AssertionError('%s: got None, want %.17g' % (label, want))
    if not isinstance(got, float):
        raise AssertionError('%s: expected a float, got %r' % (label, type(got)))
    denom = abs(want) if want != 0.0 else 1.0
    if abs(got - want) > tol * denom:
        raise AssertionError('%s: got %.17g want %.17g (rel err %.3g)'
                             % (label, got, want, abs(got - want) / denom))


def _exact_mean_var(vals):
    n = len(vals)
    fs = [_Fraction(v) for v in vals]
    m = sum(fs) / n
    var = sum((f - m) * (f - m) for f in fs) / (n - 1)
    return float(m), float(var)


def _brute_median(vals):
    s = sorted(vals)
    n = len(s)
    if n % 2:
        return s[n // 2]
    return (s[n // 2 - 1] + s[n // 2]) / 2.0


def t_basic():
    w = SlidingWindow(5)
    if w.capacity != 5:
        raise AssertionError('capacity: got %r want 5' % (w.capacity,))
    if len(w) != 0:
        raise AssertionError('len of new window: got %r want 0' % (len(w),))
    for v in (4, 1, 3):
        r = w.push(v)
        if r is not None:
            raise AssertionError('push below capacity returned %r, want None' % (r,))
    if len(w) != 3:
        raise AssertionError('len: got %r want 3' % (len(w),))
    snap = w.snapshot()
    if snap != [4.0, 1.0, 3.0]:
        raise AssertionError('snapshot: got %r want [4.0, 1.0, 3.0]' % (snap,))
    if not all(isinstance(v, float) for v in snap):
        raise AssertionError('snapshot must contain floats, got %r' % (snap,))
    _rel_close(w.mean(), 8.0 / 3.0, 1e-9, 'mean')
    _rel_close(w.variance(), 7.0 / 3.0, 1e-9, 'variance(ddof=1)')
    _rel_close(w.median(), 3.0, 1e-9, 'median')
    _rel_close(w.min(), 1.0, 1e-9, 'min')
    _rel_close(w.max(), 4.0, 1e-9, 'max')


def t_empty_and_single():
    w = SlidingWindow(3)
    for name in ('mean', 'variance', 'median', 'min', 'max'):
        got = getattr(w, name)()
        if got is not None:
            raise AssertionError('%s() on an empty window: got %r want None' % (name, got))
    if w.snapshot() != []:
        raise AssertionError('snapshot of empty window: got %r want []' % (w.snapshot(),))
    if len(w) != 0:
        raise AssertionError('len of empty window: got %r' % (len(w),))
    w.push(2.5)
    if w.variance() is not None:
        raise AssertionError('variance() with one element: got %r want None' % (w.variance(),))
    if len(w) != 1:
        raise AssertionError('len after one push: got %r want 1' % (len(w),))
    for name in ('mean', 'median', 'min', 'max'):
        _rel_close(getattr(w, name)(), 2.5, 1e-9, '%s() with one element' % name)


def t_wraparound_and_snapshot_copy():
    w = SlidingWindow(3)
    got = [w.push(i) for i in range(1, 8)]
    want = [None, None, None, 1.0, 2.0, 3.0, 4.0]
    if got != want:
        raise AssertionError('push return sequence: got %r want %r' % (got, want))
    if len(w) != 3:
        raise AssertionError('len after wraparound: got %r want 3' % (len(w),))
    if w.snapshot() != [5.0, 6.0, 7.0]:
        raise AssertionError('snapshot after wraparound: got %r want [5.0, 6.0, 7.0]'
                             % (w.snapshot(),))
    s = w.snapshot()
    s.append(999.0)
    s[0] = -1.0
    if w.snapshot() != [5.0, 6.0, 7.0]:
        raise AssertionError('snapshot() must return an independent copy; after mutating a '
                             'returned list the window reads %r' % (w.snapshot(),))
    if len(w) != 3:
        raise AssertionError('len changed after mutating a snapshot: %r' % (len(w),))
    _rel_close(w.min(), 5.0, 1e-9, 'min after wraparound')
    _rel_close(w.max(), 7.0, 1e-9, 'max after wraparound')


def t_median_even_and_duplicates():
    w = SlidingWindow(4)
    for v in (10.0, 2.0, 8.0, 4.0):
        w.push(v)
    _rel_close(w.median(), 6.0, 1e-9, 'median of even-sized window')
    w2 = SlidingWindow(2)
    w2.push(1.0)
    w2.push(2.0)
    _rel_close(w2.median(), 1.5, 1e-9, 'median of two values')
    w3 = SlidingWindow(6)
    for v in (5, 5, 5, 1, 9, 5):
        w3.push(v)
    _rel_close(w3.median(), 5.0, 1e-9, 'median with duplicates')
    _rel_close(w3.min(), 1.0, 1e-9, 'min with duplicates')
    _rel_close(w3.max(), 9.0, 1e-9, 'max with duplicates')
    w3.push(100.0)
    if w3.snapshot() != [5.0, 5.0, 1.0, 9.0, 5.0, 100.0]:
        raise AssertionError('snapshot after evicting a duplicate: got %r' % (w3.snapshot(),))
    _rel_close(w3.median(), 5.0, 1e-9, 'median after evicting one of several duplicates')


def t_invalid_capacity():
    for bad in (0, -1, -10, 5.0, 2.5, '5', None, [3]):
        try:
            SlidingWindow(bad)
        except ValueError:
            pass
        else:
            raise AssertionError('SlidingWindow(%r) should raise ValueError' % (bad,))
    w = SlidingWindow(1)
    if w.capacity != 1:
        raise AssertionError('capacity 1 window: got %r' % (w.capacity,))
    if w.push(1.0) is not None:
        raise AssertionError('first push into capacity-1 window should return None')
    if w.push(2.0) != 1.0:
        raise AssertionError('second push into capacity-1 window should return 1.0')
    if w.snapshot() != [2.0]:
        raise AssertionError('capacity-1 snapshot: got %r want [2.0]' % (w.snapshot(),))


def t_invalid_push_leaves_state():
    w = SlidingWindow(3)
    w.push(1.0)
    w.push(2.0)
    before = list(w.snapshot())
    for bad in (float('nan'), float('inf'), float('-inf'), '3', None, [1.0], complex(1, 0)):
        try:
            w.push(bad)
        except ValueError:
            pass
        else:
            raise AssertionError('push(%r) should raise ValueError' % (bad,))
        if len(w) != 2 or list(w.snapshot()) != before:
            raise AssertionError('window changed after a rejected push(%r): %r'
                                 % (bad, w.snapshot()))
    _rel_close(w.mean(), 1.5, 1e-9, 'mean after rejected pushes')
    _rel_close(w.variance(), 0.5, 1e-9, 'variance after rejected pushes')


def t_accuracy_large_values():
    vals = [1e9 + i for i in range(100)]
    w = SlidingWindow(200)
    for v in vals:
        w.push(v)
    if len(w) != 100:
        raise AssertionError('len: got %r want 100' % (len(w),))
    em, ev = _exact_mean_var(vals)
    _rel_close(w.mean(), em, 1e-9, 'mean of large near-equal values')
    _rel_close(w.variance(), ev, 1e-9, 'variance of large near-equal values')


def t_accuracy_after_evictions():
    pushed = [1e9 + (i % 37) * 0.5 for i in range(200)]
    vals = pushed[-50:]
    w = SlidingWindow(50)
    for v in pushed:
        w.push(v)
    if len(w) != 50:
        raise AssertionError('len after evictions: got %r want 50' % (len(w),))
    if w.snapshot() != vals:
        raise AssertionError('after 200 pushes at capacity 50 the window must hold the last '
                             '50 pushed values in order; got %r' % (w.snapshot(),))
    em, ev = _exact_mean_var(vals)
    _rel_close(w.mean(), em, 1e-9, 'mean of large values after evictions')
    _rel_close(w.variance(), ev, 1e-9, 'variance of large values after evictions')


def t_resize_shrink():
    w = SlidingWindow(6)
    for v in (1, 2, 3, 4, 5, 6):
        w.push(v)
    ev = w.resize(3)
    if ev != [1.0, 2.0, 3.0]:
        raise AssertionError('resize(3) must evict the OLDEST values, oldest first; got %r '
                             'want [1.0, 2.0, 3.0]' % (ev,))
    if w.capacity != 3:
        raise AssertionError('capacity after resize: got %r want 3' % (w.capacity,))
    if len(w) != 3:
        raise AssertionError('len after resize: got %r want 3' % (len(w),))
    if w.snapshot() != [4.0, 5.0, 6.0]:
        raise AssertionError('snapshot after resize: got %r want [4.0, 5.0, 6.0]'
                             % (w.snapshot(),))
    _rel_close(w.mean(), 5.0, 1e-9, 'mean after resize')
    _rel_close(w.variance(), 1.0, 1e-9, 'variance after resize')
    _rel_close(w.median(), 5.0, 1e-9, 'median after resize')
    _rel_close(w.min(), 4.0, 1e-9, 'min after resize')
    _rel_close(w.max(), 6.0, 1e-9, 'max after resize')
    if w.push(7) != 4.0:
        raise AssertionError('push after shrinking should evict 4.0 at the new capacity')
    if w.snapshot() != [5.0, 6.0, 7.0]:
        raise AssertionError('snapshot after push at new capacity: got %r' % (w.snapshot(),))


def t_resize_grow_and_invalid():
    w = SlidingWindow(2)
    w.push(1)
    w.push(2)
    ev = w.resize(4)
    if ev != []:
        raise AssertionError('growing resize should return []; got %r' % (ev,))
    if w.capacity != 4:
        raise AssertionError('capacity after growing: got %r want 4' % (w.capacity,))
    if w.snapshot() != [1.0, 2.0]:
        raise AssertionError('snapshot after growing: got %r want [1.0, 2.0]' % (w.snapshot(),))
    if w.push(3) is not None or w.push(4) is not None:
        raise AssertionError('pushes below the new capacity should return None')
    if w.push(5) != 1.0:
        raise AssertionError('push at the new capacity should evict 1.0')
    if w.snapshot() != [2.0, 3.0, 4.0, 5.0]:
        raise AssertionError('snapshot: got %r want [2.0, 3.0, 4.0, 5.0]' % (w.snapshot(),))
    if w.resize(4) != []:
        raise AssertionError('resize to the same capacity should return []')
    before = list(w.snapshot())
    for bad in (0, -3, 2.0, 'x', None):
        try:
            w.resize(bad)
        except ValueError:
