    w = SlidingWindow(4)
    for v in (100.0, -50.0, 7.0):
        w.push(v)
    if w.clear() is not None:
        raise AssertionError('clear() must return None')
    if len(w) != 0:
        raise AssertionError('len after clear: got %r want 0' % (len(w),))
    if w.capacity != 4:
        raise AssertionError('capacity after clear: got %r want 4' % (w.capacity,))
    if w.snapshot() != []:
        raise AssertionError('snapshot after clear: got %r want []' % (w.snapshot(),))
    for name in ('mean', 'variance', 'median', 'min', 'max'):
        got = getattr(w, name)()
        if got is not None:
            raise AssertionError('%s() after clear: got %r want None' % (name, got))
    w.push(3.0)
    w.push(5.0)
    _rel_close(w.mean(), 4.0, 1e-9, 'mean after clear and reuse')
    _rel_close(w.variance(), 2.0, 1e-9, 'variance after clear and reuse')
    _rel_close(w.median(), 4.0, 1e-9, 'median after clear and reuse')
    _rel_close(w.min(), 3.0, 1e-9, 'min after clear and reuse')
    _rel_close(w.max(), 5.0, 1e-9, 'max after clear and reuse')


def t_invariants_against_bruteforce():
    rng = _random.Random(20260825)
    w = SlidingWindow(7)
    ref = []
    for step in range(400):
        v = float(rng.randrange(-5, 6))
        want_ev = ref[0] if len(ref) == 7 else None
        got_ev = w.push(v)
        if len(ref) == 7:
            ref.pop(0)
        ref.append(v)
        if got_ev != want_ev:
            raise AssertionError('step %d: push returned %r want %r' % (step, got_ev, want_ev))
        if len(w) != len(ref):
            raise AssertionError('step %d: len %r want %r' % (step, len(w), len(ref)))
        if w.snapshot() != ref:
            raise AssertionError('step %d: snapshot %r want %r' % (step, w.snapshot(), ref))
        n = len(ref)
        _rel_close(w.median(), _brute_median(ref), 1e-9, 'step %d median' % step)
        _rel_close(w.min(), min(ref), 1e-9, 'step %d min' % step)
        _rel_close(w.max(), max(ref), 1e-9, 'step %d max' % step)
        mu = sum(ref) / n
        _rel_close(w.mean(), mu, 1e-9, 'step %d mean' % step)
        if n >= 2:
            var = sum((x - mu) * (x - mu) for x in ref) / (n - 1)
            _rel_close(w.variance(), var, 1e-9, 'step %d variance' % step)
        elif w.variance() is not None:
            raise AssertionError('step %d: variance with one element must be None' % step)


def t_performance():
    rng = _random.Random(7)
    cap = 10000
    vals = [rng.random() * 1000.0 for _ in range(40000)]
    w = SlidingWindow(cap)
    t0 = _time.perf_counter()
    acc = 0.0
    for v in vals:
        w.push(v)
        m = w.median()
        if m is None:
            raise AssertionError('median() returned None during the benchmark')
        acc += m
    elapsed = _time.perf_counter() - t0
    if len(w) != cap:
        raise AssertionError('len after benchmark: got %r want %r' % (len(w), cap))
    _rel_close(w.median(), _brute_median(vals[-cap:]), 1e-9, 'median at end of benchmark')
    if not _math.isfinite(acc):
