import math


def rolling_mean(times, values, width, min_count=1):
    n = len(times)
    if n != len(values):
        raise ValueError("times and values must have the same length")
    if not math.isfinite(width) or width <= 0:
        raise ValueError("width must be a finite positive number")
    if min_count < 1:
        raise ValueError("min_count must be >= 1")
    for i in range(1, n):
        if not (times[i] > times[i - 1]):
            raise ValueError("times must be strictly increasing")

    out = []
    lo = 0
    s = 0.0   # running sum, Neumaier compensated
    c = 0.0   # lost low-order bits

    def add(x):
        nonlocal s, c
        t = s + x
        if abs(s) >= abs(x):
            c += (s - t) + x
        else:
            c += (x - t) + s
        s = t

    for i in range(n):
        add(float(values[i]))
        cutoff = times[i] - width
        # half-open window: a sample exactly at the cutoff is OUT.
        # `lo < i` keeps the current point in its own window.
        while lo < i and times[lo] <= cutoff:
            add(-float(values[lo]))
            lo += 1
        count = i - lo + 1
        if count < min_count:
            out.append(None)
        else:
            out.append((s + c) / count)
    return out

