import math
import re
from fractions import Fraction

_NAME_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')


class SpecError(Exception):
    def __init__(self, message='', index=None):
        super().__init__(message)
        self.index = index


class SpecTypeError(SpecError, TypeError):
    def __init__(self, message='', argname=None):
        SpecError.__init__(self, message, None)
        self.argname = argname


class SpecSyntaxError(SpecError, ValueError):
    pass


class SpecValueError(SpecError, ValueError):
    pass


class DuplicateNameError(SpecValueError):
    def __init__(self, message='', index=None, name=None):
        SpecValueError.__init__(self, message, index)
        self.name = name


class CapacityError(SpecError, ValueError):
    pass


def allocate(spec, capacity):
    # 1. argument types, spec before capacity
    if not isinstance(spec, str):
        raise SpecTypeError('spec must be str, got %s' % type(spec).__name__, 'spec')
    if isinstance(capacity, bool) or not isinstance(capacity, int):
        raise SpecTypeError('capacity must be a non-bool int', 'capacity')
    # 2. capacity range, before any parsing (including the empty-spec shortcut)
    if capacity < 0:
        raise CapacityError('capacity must be non-negative')
    if spec.strip() == '':
        return {}

    names = []
    weights = []
    seen = set()
    for i, raw in enumerate(spec.split(',')):
        if raw.count('=') != 1:
            raise SpecSyntaxError('entry %d: expected exactly one "="' % i, i)
        nm, wt = raw.split('=')
        nm = nm.strip()
        wt = wt.strip()
        if _NAME_RE.fullmatch(nm) is None:
            raise SpecSyntaxError('entry %d: bad name %r' % (i, nm), i)
        try:
            w = float(wt)
        except ValueError:
            raise SpecSyntaxError('entry %d: unparseable weight %r' % (i, wt), i)
        if math.isnan(w) or math.isinf(w):
            raise SpecValueError('entry %d: weight must be finite' % i, i)
        if w < 0.0:
            raise SpecValueError('entry %d: weight must not be negative' % i, i)
        if nm in seen:
            raise DuplicateNameError('entry %d: duplicate name %r' % (i, nm), i, nm)
        seen.add(nm)
        names.append(nm)
        weights.append(Fraction(w))

    total = sum(weights, Fraction(0))
    if total == 0:
        return dict((n, 0) for n in names)

    cap = Fraction(capacity)
    base = []
    rem = []
    for w in weights:
        q = cap * w / total
        b = math.floor(q)
        base.append(b)
        rem.append(q - b)
    left = capacity - sum(base)
    order = sorted(range(len(names)), key=lambda i: (-rem[i], i))
    for i in order[:left]:
        base[i] += 1
    return dict((names[i], int(base[i])) for i in range(len(names)))

