import math

import numpy as np

_NEG_INF = float("-inf")
_POS_INF = float("inf")


def log_sum_exp(xs):
    vals = []
    for x in xs:
        x = float(x)
        if math.isnan(x) or x == _POS_INF:
            raise ValueError("log_sum_exp: entry is NaN or +inf")
        vals.append(x)
    finite = [x for x in vals if x != _NEG_INF]
    if not finite:
        return _NEG_INF
    L = max(finite)
    s = math.fsum(math.exp(x - L) for x in finite)
    return float(L + math.log(s))


def weighted_quantile(values, log_weights, qs):
    vals = [float(v) for v in values]
    lws = [float(w) for w in log_weights]
    if len(vals) != len(lws):
        raise ValueError("weighted_quantile: length mismatch")
    for v in vals:
        if not math.isfinite(v):
            raise ValueError("weighted_quantile: non-finite value")
    for w in lws:
        if math.isnan(w) or w == _POS_INF:
            raise ValueError("weighted_quantile: invalid log weight")
    qlist = []
    for q in qs:
        q = float(q)
        if math.isnan(q) or q < 0.0 or q > 1.0:
            raise ValueError("weighted_quantile: q outside [0, 1]")
        qlist.append(q)

    pairs = [(v, w) for v, w in zip(vals, lws) if w != _NEG_INF]
    if not pairs:
        raise ValueError("weighted_quantile: no entry with positive weight")

    L = max(w for _, w in pairs)
    kept = []
    for v, w in pairs:
        t = math.exp(w - L)
        if t != 0.0:
            kept.append((v, t))
    # kept is non-empty: the entry attaining L has t == 1.0

    groups = {}
    for v, t in kept:
        groups[v] = groups.get(v, 0.0) + t
    us = sorted(groups)
    m = len(us)

    if not qlist:
        return []
    if m == 1:
        return [us[0]] * len(qlist)

    Z = math.fsum(groups[u] for u in us)
    ws = [groups[u] / Z for u in us]

    C = []
    acc = 0.0
    for w in ws:
        acc += w
        C.append(acc)
    p = [C[k] - 0.5 * ws[k] for k in range(m)]
    lo = p[0]
    denom = p[-1] - p[0]
    h = [(pk - lo) / denom for pk in p]
    h[0] = 0.0
    h[-1] = 1.0

    h_arr = np.asarray(h, dtype=float)
    q_arr = np.asarray(qlist, dtype=float)
    idx = np.searchsorted(h_arr, q_arr, side="right") - 1
    idx = np.clip(idx, 0, m - 2)

    out = []
    for q, k in zip(qlist, idx.tolist()):
        if q <= 0.0:
            out.append(us[0])
        elif q >= 1.0:
            out.append(us[-1])
        else:
            out.append(us[k] + (q - h[k]) * (us[k + 1] - us[k]) / (h[k + 1] - h[k]))
    return [float(x) for x in out]

import re

_MONTHS = {'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
           'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12}

_ISO_RE = re.compile(r'(\d{4})-(\d{2})-(\d{2})\Z')
_SLASH_RE = re.compile(r'(\d{1,2})/(\d{1,2})/(\d{4})\Z')
_NAME_RE = re.compile(r'(\d{1,2}) +([A-Za-z]{3}) +(\d{4})\Z')
_MAG_RE = re.compile(r'[0-9.,]+\Z')


def _days_in_month(y, m):
    if m in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if m in (4, 6, 9, 11):
        return 30
    leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
    return 29 if leap else 28


def _valid_ymd(y, m, d):
    if not (1000 <= y <= 9999):
        return False
    if not (1 <= m <= 12):
        return False
    return 1 <= d <= _days_in_month(y, m)


def _fmt(y, m, d):
    return '%04d-%02d-%02d' % (y, m, d)


def _split_fields(line):
    """Return the list of field values, or None if the line is badly quoted."""
    fields = []
    i = 0
    n = len(line)
    while True:
        while i < n and line[i] in ' \t':
            i += 1
        if i < n and line[i] == '"':
            i += 1
            buf = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1
                    closed = True
                    break
                buf.append(c)
                i += 1
            if not closed:
                return None
            while i < n and line[i] in ' \t':
                i += 1
            if i < n and line[i] != ',':
                return None
            fields.append(''.join(buf))
            if i < n:
                i += 1
                continue
            return fields
        else:
            j = i
            while j < n and line[j] != ',':
                j += 1
            fields.append(line[i:j].strip(' \t'))
            if j < n:
                i = j + 1
                continue
            return fields


def _parse_date(raw):
    s = raw.strip(' \t')
    m = _ISO_RE.match(s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        return _fmt(y, mo, d) if _valid_ymd(y, mo, d) else None
    m = _SLASH_RE.match(s)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if _valid_ymd(y, b, a):
            return _fmt(y, b, a)
        if _valid_ymd(y, a, b):
            return _fmt(y, a, b)
        return None
    m = _NAME_RE.match(s)
    if m:
        d = int(m.group(1))
        mo = _MONTHS.get(m.group(2).lower())
        y = int(m.group(3))
        if mo is not None and _valid_ymd(y, mo, d):
            return _fmt(y, mo, d)
        return None
    return None


def _parse_amount(raw):
    s = raw.strip(' \t')
    if s == '':
        return None
    neg_paren = False
    if len(s) >= 2 and s[0] == '(' and s[-1] == ')':
        neg_paren = True
        s = s[1:-1].strip(' \t')
    elif s[0] == '(' or s[-1] == ')':
        return None
    sign_neg = False
    has_sign = False
    if s[:1] in ('+', '-'):
        has_sign = True
        sign_neg = (s[0] == '-')
        s = s[1:]
    if neg_paren and has_sign:
        return None
    if s[:1] == '$':
        s = s[1:]
    pct = False
    if s[-1:] == '%':
        pct = True
        s = s[:-1]
    if s == '' or not _MAG_RE.match(s):
        return None

    has_c = ',' in s
    has_d = '.' in s
    if has_c and has_d:
        if s.rindex(',') > s.rindex('.'):
            dec, grp = ',', '.'
        else:
            dec, grp = '.', ','
    elif has_c:
        parts = s.split(',')
        if all(len(p) == 3 and p.isdigit() for p in parts[1:]):
            dec, grp = None, ','
        else:
            dec, grp = ',', None
    elif has_d:
        if s.count('.') >= 2:
            dec, grp = None, '.'
        else:
            dec, grp = '.', None
    else:
        dec, grp = None, None

    if dec is not None:
        if s.count(dec) != 1:
            return None
        int_part, frac = s.split(dec)
        if frac == '' or not frac.isdigit():
            return None
    else:
        int_part, frac = s, ''

    if grp is not None:
        groups = int_part.split(grp)
        if len(groups) < 2:
            return None
        if not (1 <= len(groups[0]) <= 3) or not groups[0].isdigit():
            return None
        for g in groups[1:]:
            if len(g) != 3 or not g.isdigit():
                return None
        digits = ''.join(groups)
    else:
        if int_part == '' or not int_part.isdigit():
            return None
        digits = int_part

    val = float(digits + '.' + (frac if frac else '0'))
    if pct:
        val = val / 100.0
    if neg_paren or sign_neg:
        val = -val
    return val


def parse_records(text):
    if not isinstance(text, str):
        raise TypeError('text must be a str')
    records = []
    errors = []
    pos_of = {}
    for idx, raw in enumerate(text.split('\n')):
        lineno = idx + 1
        line = raw[:-1] if raw.endswith('\r') else raw
        stripped = line.strip(' \t')
        if stripped == '':
            continue
        if stripped[0] == '#':
            continue
        fields = _split_fields(line)
        if fields is None:
            errors.append((lineno, 'BAD_QUOTE'))
            continue
        if len(fields) not in (3, 4):
            errors.append((lineno, 'FIELD_COUNT'))
            continue
        rid = fields[0]
        if rid.strip(' \t') == '':
            errors.append((lineno, 'BAD_ID'))
            continue
        date = _parse_date(fields[1])
        if date is None:
            errors.append((lineno, 'BAD_DATE'))
            continue
        amount = _parse_amount(fields[2])
        if amount is None:
            errors.append((lineno, 'BAD_AMOUNT'))
            continue
        note = fields[3] if len(fields) == 4 else ''
        rec = {'id': rid, 'date': date, 'amount': amount, 'note': note}
        if rid in pos_of:
            records[pos_of[rid]] = rec
        else:
            pos_of[rid] = len(records)
            records.append(rec)
    return records, errors

