    m = _SLASH.match(s)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        out = _mk(y, a, b)
        if out is not None:
            return out
        return _mk(y, b, a)
    m = _NAME.match(s)
    if m:
        mo = _MONTHS.get(m.group(2)[:3].lower())
        if mo is None:
            return None
        return _mk(int(m.group(3)), mo, int(m.group(1)))
    return None


_NUM = re.compile(r'^(\d{1,3}(,\d{3})*|\d+)(\.\d+)?$')


def _parse_amount(raw):
    s = raw.strip()
    if not s:
        return None
    neg = False
    if s.startswith('(') and s.endswith(')'):
        neg = True
        s = s[1:-1].strip()
    pct = False
    if s.endswith('%'):
        pct = True
        s = s[:-1]
    if s.startswith('+'):
        s = s[1:]
    elif s.startswith('-'):
        neg = not neg
        s = s[1:]
    if s.startswith('$'):
        s = s[1:]
    if not _NUM.match(s):
        return None
    val = float(s.replace(',', ''))
    if pct:
        val = val / 100.0
    if neg:
        val = -val
    return val


def parse_records(text):
    if not isinstance(text, str):
        raise TypeError('text must be a str')
    records = []
    errors = []
    for idx, line in enumerate(text.split('\n')):
        lineno = idx + 1
        if line.strip() == '' or line.strip().startswith('#'):
            continue
        try:
            fields = next(csv.reader([line]))
        except Exception:
            errors.append((lineno, 'BAD_QUOTE'))
            continue
        fields = [f.strip() for f in fields]
        if len(fields) not in (3, 4):
            errors.append((lineno, 'FIELD_COUNT'))
            continue
        if fields[0] == '':
            errors.append((lineno, 'BAD_ID'))
            continue
        d = _parse_date(fields[1])
        if d is None:
            errors.append((lineno, 'BAD_DATE'))
            continue
        a = _parse_amount(fields[2])
        if a is None:
            errors.append((lineno, 'BAD_AMOUNT'))
            continue
        note = fields[3] if len(fields) == 4 else ''
        records.append({'id': fields[0], 'date': d, 'amount': a, 'note': note})
    return records, errors

