def _zz_guard(fn):
    def _wrapped():
        try:
            return fn()
        except AssertionError:
            raise
        except Exception as _e:
            raise AssertionError('%s: %s' % (type(_e).__name__, _e))
    return _wrapped


def _zz_name(n):
    g = globals()
    if n not in g:
        raise AssertionError('required name %r is not defined' % (n,))
    return g[n]


def _zz_eq(got, want, label):
    if got != want:
        raise AssertionError('%s: got %r want %r' % (label, got, want))


def _zz_value_error(fn, want_msg):
    try:
        fn()
    except ValueError as e:
        if str(e) != want_msg:
            raise AssertionError('ValueError message %r, want %r' % (str(e), want_msg))
        return
    except AssertionError:
        raise
    except Exception as e:
        raise AssertionError('raised %s(%s), want ValueError %r' % (type(e).__name__, e, want_msg))
    raise AssertionError('no exception raised, want ValueError %r' % (want_msg,))


def _zz_key_error(fn, label):
    try:
        fn()
    except KeyError:
        return
    except AssertionError:
        raise
    except Exception as e:
        raise AssertionError('%s: raised %s(%s), want KeyError' % (label, type(e).__name__, e))
    raise AssertionError('%s: no exception raised, want KeyError' % (label,))


