def t_linear_time():
    import time
    adjust = _zz_name('adjust')
    n = 200000
    recs = []
    for i in range(n):
        m = i % 4
        if m == 0:
            recs.append({'kind': 'raw', 'value': (i % 53) * 0.25})
        elif m == 1:
            recs.append({'kind': 'scaled', 'value': (i % 97) * 0.01, 'gain': 1.5})
        elif m == 2:
            recs.append({'kind': 'skip'})
        else:
            recs.append({'kind': 'offset', 'value': (i % 89) * 0.5, 'bias': -1.0})
    t0 = time.perf_counter()
    got = adjust(recs)
    dt = time.perf_counter() - t0
    if len(got) != n:
        raise AssertionError('adjust returned %d rows for %d records' % (len(got), n))
    if sorted(got[-1].keys()) != ['i', 'kind', 'total', 'value']:
        raise AssertionError('row keys %r' % (sorted(got[-1].keys()),))
    if got[-1]['i'] != n - 1:
        raise AssertionError('last row index %r want %r' % (got[-1]['i'], n - 1))
    if dt > 10.0:
        raise AssertionError('adjust took %.2f s for %d records; it must run in linear time'
                             % (dt, n))


